(84715, 3167, 878, '<td valign="top">Good macro, nice detail and colors.</td>', 'Good macro, nice detail and colors.', '2002-07-17 00:55:00.000000', NULL, 1),
(84716, 3167, 1793, '<td valign="top">the eye in the snake''s eye is what making me give this a 10.</td>', 'the eye in the snake''s eye is what making me give this a 10.', '2002-07-17 04:27:00.000000', NULL, 1),
(84717, 3167, 2466, '<td valign="top">This is so cool</td>', 'This is so cool', '2002-07-17 11:12:00.000000', NULL, 1),
