(85080, 3192, 1280, '<td valign="top">could be lighter</td>', 'could be lighter', '2002-07-21 10:09:00.000000', NULL, 1),
(85081, 3192, 1054, '<td valign="top">Excellent work, the water drops look almost rendered. 9-ClubJuggle</td>', 'Excellent work, the water drops look almost rendered. 9-ClubJuggle', '2002-07-21 13:18:00.000000', NULL, 1),
(85082, 3192, 2721, '<td valign="top">What kind of flower is that?</td>', 'What kind of flower is that?', '2002-07-21 22:10:00.000000', NULL, 1),
(85083, 3192, 2, '<td valign="top">Really awesome image, but as sick as you may be of hearing it, I''d much rather see this in color -- everything is very middle-gray in the shot, and I think that takes the excitement out.</td>', 'Really awesome image, but as sick as you may be of hearing it, I''d much rather see this in color -- everything is very middle-gray in the shot, and I think that takes the excitement out.', '2002-07-22 00:48:00.000000', NULL, 1),
(85084, 3192, 2188, '<td valign="top">Very nice!</td>', 'Very nice!', '2002-07-22 00:59:00.000000', NULL, 1),
(85085, 3192, 2467, '<td valign="top">What kind of flower is that?<br/>  - These aren''t flowers, they''re actually Taro leaves.<br/><br/>About the color...I would''ve submitted a color version, but it really didn''t look good at all.</td>', 'What kind of flower is that?  - These aren''t flowers, they''re actually Taro leaves.About the color...I would''ve submitted a color version, but it really didn''t look good at all.', '2002-07-22 03:48:00.000000', NULL, 0),
(85086, 3192, 472, '<td valign="top">i think this is awesome but i think that oyu could have improved it by increasing the tonal range in your favorite image editor.<br/></td>', 'i think this is awesome but i think that oyu could have improved it by increasing the tonal range in your favorite image editor.', '2002-07-22 10:20:00.000000', NULL, 0);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(85087, 3194, 133, '<td valign="top">Great facial capture.</td>', 'Great facial capture.', '2002-07-15 08:50:00.000000', NULL, 1),
(85088, 3194, 1175, '<td valign="top">ooooohhhh... if only you were a bit to the left to catch all the expression on his face.</td>', 'ooooohhhh... if only you were a bit to the left to catch all the expression on his face.', '2002-07-15 10:17:00.000000', NULL, 1),
(85089, 3194, 1779, '<td valign="top">nice... a bit more of contrast would''ve been nice.</td>', 'nice... a bit more of contrast would''ve been nice.', '2002-07-15 13:21:00.000000', NULL, 1),
(85090, 3194, 2123, '<td valign="top">Love the expression on his face!  Maybe a tad light, but a great photo, it really conveys emotion well.</td>', 'Love the expression on his face!  Maybe a tad light, but a great photo, it really conveys emotion well.', '2002-07-15 14:30:00.000000', NULL, 1),
(85091, 3194, 1944, '<td valign="top">Nicely done portrait. The bow is just blurred enough to give it life. The background however is a bit distracting.</td>', 'Nicely done portrait. The bow is just blurred enough to give it life. The background however is a bit distracting.', '2002-07-15 14:33:00.000000', NULL, 1),
(85092, 3194, 2152, '<td valign="top">Nice shot and I like the motion of whatever that thing''s called. But I think it could benefit from some more contrast and a less distracting background.</td>', 'Nice shot and I like the motion of whatever that thing''s called. But I think it could benefit from some more contrast and a less distracting background.', '2002-07-15 14:50:00.000000', NULL, 1),
(85093, 3194, 1041, '<td valign="top">b&amp;w works well here, i like the subject, blurred background is also good, just the bow straight through the face is distracting. of course, i don''t know the circumstances of the shot, was there a way to move around a little to the left? -- gr8photos (6)</td>', 'b&w works well here, i like the subject, blurred background is also good, just the bow straight through the face is distracting. of course, i don''t know the circumstances of the shot, was there a way to move around a little to the left? -- gr8photos (6)', '2002-07-15 15:22:00.000000', NULL, 1),
(85094, 3194, 2195, '<td valign="top">you caught the emotion well but would help if you would have waited till the bow was a bit more horizontal so its not in his face as much</td>', 'you caught the emotion well but would help if you would have waited till the bow was a bit more horizontal so its not in his face as much', '2002-07-15 17:08:00.000000', NULL, 1),
(85095, 3194, 573, '<td valign="top">Beautifull photograph and good choice for grey tone, IMO a slight change of camera position could have greatly improved an otherwise exclent comopsition (pun intended).</td>', 'Beautifull photograph and good choice for grey tone, IMO a slight change of camera position could have greatly improved an otherwise exclent comopsition (pun intended).', '2002-07-15 17:34:00.000000', NULL, 1),
(85096, 3194, 1859, '<td valign="top">Nice shot.</td>', 'Nice shot.', '2002-07-15 18:02:00.000000', NULL, 1),
(85097, 3194, 2734, '<td valign="top">Beautiful capture of mood !</td>', 'Beautiful capture of mood !', '2002-07-15 18:07:00.000000', NULL, 1),
(85098, 3194, 327, '<td valign="top">Rock on.</td>', 'Rock on.', '2002-07-15 18:12:00.000000', NULL, 1),
(85099, 3194, 1360, '<td valign="top">I just love the feeling of emotion I get from the player''s face in this photo.</td>', 'I just love the feeling of emotion I get from the player''s face in this photo.', '2002-07-15 20:44:00.000000', NULL, 1),
(85100, 3194, 2722, '<td valign="top">Super b&amp;w, only if the bow wasn''t across the face -8</td>', 'Super b&w, only if the bow wasn''t across the face -8', '2002-07-15 21:11:00.000000', NULL, 1),
(85101, 3194, 2553, '<td valign="top">I can almost feel and hear the music...</td>', 'I can almost feel and hear the music...', '2002-07-15 21:14:00.000000', NULL, 1),
(85102, 3194, 889, '<td valign="top">gee and I thought he was sleeping. choosing black and white doesnt seem important in this picture. texture and expression might be better with the color. Focus is good. depth of field is good.</td>', 'gee and I thought he was sleeping. choosing black and white doesnt seem important in this picture. texture and expression might be better with the color. Focus is good. depth of field is good.', '2002-07-15 21:56:00.000000', NULL, 1),
(85103, 3194, 318, '<td valign="top">I can almost hear him, great shot!</td>', 'I can almost hear him, great shot!', '2002-07-15 22:29:00.000000', NULL, 1),
(85104, 3194, 2, '<td valign="top">I''d like to see the head of the violin (?) in the framing.  I really appreciate the emotion you''ve captured, though.</td>', 'I''d like to see the head of the violin (?) in the framing.  I really appreciate the emotion you''ve captured, though.', '2002-07-15 22:50:00.000000', NULL, 1),
(85105, 3194, 2058, '<td valign="top">Great shot!  I like how the bow and the angle of the head almost line up, and his expression is just great... really lets you see how he is feeling.</td>', 'Great shot!  I like how the bow and the angle of the head almost line up, and his expression is just great... really lets you see how he is feeling.', '2002-07-16 02:39:00.000000', NULL, 1),
(85106, 3194, 1569, '<td valign="top">The face being obscured by the bow,destroys the mood of this one.This is just my take on this.</td>', 'The face being obscured by the bow,destroys the mood of this one.This is just my take on this.', '2002-07-16 12:29:00.000000', NULL, 1),
(85107, 3194, 772, '<td valign="top">I think this would be a phenomenal image on a dark background, but I know that was impossible on this shot... good work :) = 7 - jmsetzler</td>', 'I think this would be a phenomenal image on a dark background, but I know that was impossible on this shot... good work :) = 7 - jmsetzler', '2002-07-16 19:27:00.000000', NULL, 1),
(85108, 3194, 2481, '<td valign="top">bow is cutting into composition and covering face; face has great expression; dark in foreground works well</td>', 'bow is cutting into composition and covering face; face has great expression; dark in foreground works well', '2002-07-17 09:58:00.000000', NULL, 1),
(85109, 3194, 2334, '<td valign="top">the end of the bow is blurry..nice anyway.</td>', 'the end of the bow is blurry..nice anyway.', '2002-07-17 11:29:00.000000', NULL, 1),
(85110, 3194, 2256, '<td valign="top">great capture, I might have tried to keep the whole violin in the shot.....</td>', 'great capture, I might have tried to keep the whole violin in the shot.....', '2002-07-17 11:36:00.000000', NULL, 1),
(85111, 3194, 689, '<td valign="top">I like the B&amp;W ... photo shows a lot of emotion .... good job!</td>', 'I like the B&W ... photo shows a lot of emotion .... good job!', '2002-07-17 12:27:00.000000', NULL, 1),
(85112, 3194, 671, '<td valign="top">good pose.  It catches the mood well.</td>', 'good pose.  It catches the mood well.', '2002-07-17 13:57:00.000000', NULL, 1),
(85113, 3194, 1748, '<td valign="top">great mood in ths image pity about the b/g&amp; the bow hidding so much of the expression on the players face, still a good image</td>', 'great mood in ths image pity about the b/g& the bow hidding so much of the expression on the players face, still a good image', '2002-07-17 21:00:00.000000', NULL, 1),
(85114, 3194, 1031, '<td valign="top">I like the composition and control of DOF. Whether or not I prefer this in grayscale depends on the original color of that electric fiddle.</td>', 'I like the composition and control of DOF. Whether or not I prefer this in grayscale depends on the original color of that electric fiddle.', '2002-07-18 03:33:00.000000', NULL, 1),
(85115, 3194, 1005, '<td valign="top">Nice shot, maybe a bit grey, especially the background, but wonderful capture of the artist''s emotion.  7 Swash</td>', 'Nice shot, maybe a bit grey, especially the background, but wonderful capture of the artist''s emotion.  7 Swash', '2002-07-18 15:11:00.000000', NULL, 1),
(85116, 3194, 640, '<td valign="top">Really tells a story. Great candid shot.</td>', 'Really tells a story. Great candid shot.', '2002-07-19 04:14:00.000000', NULL, 1),
(85117, 3194, 2777, '<td valign="top">Tent is taking too much attention, and violin which is in focus is too low, and even more not completely in picture.</td>', 'Tent is taking too much attention, and violin which is in focus is too low, and even more not completely in picture.', '2002-07-19 06:18:00.000000', NULL, 1),
(85118, 3194, 2798, '<td valign="top">Great shot. Personally I''d tweak the contrast up a shade.</td>', 'Great shot. Personally I''d tweak the contrast up a shade.', '2002-07-19 14:16:00.000000', NULL, 1),
(85119, 3194, 2752, '<td valign="top">I feel it</td>', 'I feel it', '2002-07-20 21:01:00.000000', NULL, 1),
(85120, 3194, 255, '<td valign="top">very nice. a little grey on my monitor--nothing a little contrast would help! 9--amitchell</td>', 'very nice. a little grey on my monitor--nothing a little contrast would help! 9--amitchell', '2002-07-21 04:47:00.000000', NULL, 1),
(85121, 3194, 741, '<td valign="top">Love the composition - would have been even better if the bow didn''t cross his eye like that - wait for him to use one of the other strings?</td>', 'Love the composition - would have been even better if the bow didn''t cross his eye like that - wait for him to use one of the other strings?', '2002-07-21 07:22:00.000000', NULL, 1),
(85122, 3194, 2428, '<td valign="top">the violin "thing" gets in the way of the expression, and it lacks contrast.</td>', 'the violin "thing" gets in the way of the expression, and it lacks contrast.', '2002-07-21 14:21:00.000000', NULL, 1),
(85123, 3194, 1759, '<td valign="top">Interesting composition. Kudos for taking a bold departure from the typical straight on view. Good job.</td>', 'Interesting composition. Kudos for taking a bold departure from the typical straight on view. Good job.', '2002-07-21 17:16:00.000000', NULL, 1),
(85124, 3194, 2721, '<td valign="top">I want a violin like that.</td>', 'I want a violin like that.', '2002-07-21 19:23:00.000000', NULL, 1),
(85125, 3194, 811, '<td valign="top">I like the emotion on his face and how the bow, the tilt of his neck and the tent (?) all lead to the right.  Black and white also gives it a "mood" that may be lost in color.</td>', 'I like the emotion on his face and how the bow, the tilt of his neck and the tent (?) all lead to the right.  Black and white also gives it a "mood" that may be lost in color.', '2002-07-21 20:22:00.000000', NULL, 1),
(85126, 3194, 1078, '<td valign="top">Oh that the bow were being held in a position that didn''t cover his face.  I don''t know where you were and this was probably impossible, but I wish this could have been from seveal feet to the left.  The tonal range on this seems a little flat overall -- the only real shadows/blacks are around the violin -- would be nice if ther est wasn''t quite so grey.</td>', 'Oh that the bow were being held in a position that didn''t cover his face.  I don''t know where you were and this was probably impossible, but I wish this could have been from seveal feet to the left.  The tonal range on this seems a little flat overall -- the only real shadows/blacks are around the violin -- would be nice if ther est wasn''t quite so grey.', '2002-07-22 00:07:00.000000', NULL, 1),
(85127, 3194, 2188, '<td valign="top">I would have liked this better if it weren''t so tight I think. Great moment though.</td>', 'I would have liked this better if it weren''t so tight I think. Great moment though.', '2002-07-22 01:02:00.000000', NULL, 0),
(85128, 3196, 133, '<td valign="top">Gorgeous blue sky and green grass.</td>', 'Gorgeous blue sky and green grass.', '2002-07-15 08:43:00.000000', NULL, 1),
(85129, 3196, 1175, '<td valign="top">Good loolking sky.  I like the angle in the landscape between the grassy area and the brown dirt area.  Nice composition.</td>', 'Good loolking sky.  I like the angle in the landscape between the grassy area and the brown dirt area.  Nice composition.', '2002-07-15 09:50:00.000000', NULL, 1),
(85130, 3196, 889, '<td valign="top">the horizon looks nice at this time of your.</td>', 'the horizon looks nice at this time of your.', '2002-07-15 11:04:00.000000', NULL, 1),
(85131, 3196, 1779, '<td valign="top">nice...</td>', 'nice...', '2002-07-15 14:13:00.000000', NULL, 1),
(85132, 3196, 327, '<td valign="top">Pretty area. Good color. Kee</td>', 'Pretty area. Good color. Kee', '2002-07-15 16:57:00.000000', NULL, 1),
(85133, 3196, 2058, '<td valign="top">A nice landscape shot.  You might want to focus more on the ruins though, since that is the title of the image.</td>', 'A nice landscape shot.  You might want to focus more on the ruins though, since that is the title of the image.', '2002-07-15 17:27:00.000000', NULL, 1),
(85134, 3196, 2146, '<td valign="top">very pretty, I want to live here</td>', 'very pretty, I want to live here', '2002-07-15 20:15:00.000000', NULL, 1),
(85135, 3196, 1543, '<td valign="top">love the clouds!</td>', 'love the clouds!', '2002-07-15 21:29:00.000000', NULL, 1),
(85136, 3196, 2553, '<td valign="top">Like this photo very much. <br/><br/><br/></td>', 'Like this photo very much. ', '2002-07-15 21:41:00.000000', NULL, 1),
(85137, 3196, 2649, '<td valign="top">Composition is excellent.  I especially like the clouds, very nice photo.</td>', 'Composition is excellent.  I especially like the clouds, very nice photo.', '2002-07-16 00:09:00.000000', NULL, 1),
(85138, 3196, 1280, '<td valign="top">Aside from the title, it''s difficult to tell where to focus.  The tree competes.  A bare landscape as a setting for the ruin would be more dramatic.  Just by moving you could have changed your perspective.  Great coloring. Wonderful clouds.</td>', 'Aside from the title, it''s difficult to tell where to focus.  The tree competes.  A bare landscape as a setting for the ruin would be more dramatic.  Just by moving you could have changed your perspective.  Great coloring. Wonderful clouds.', '2002-07-16 01:25:00.000000', NULL, 1),
