(85297, 3213, 668, '<td valign="top">very interesting. nice title</td>', 'very interesting. nice title', '2002-07-17 19:01:00.000000', NULL, 1),
(85298, 3213, 1041, '<td valign="top">it does look kind of freeze-dried, doesn''t it.  the photo is very busy and not really sharp enough i think.  also not enough contrast, especially between the plants on the right.  unfortunately, i''m not sure what to say to try doing differently. :( -- gr8photos (3)</td>', 'it does look kind of freeze-dried, doesn''t it.  the photo is very busy and not really sharp enough i think.  also not enough contrast, especially between the plants on the right.  unfortunately, i''m not sure what to say to try doing differently. :( -- gr8photos (3)', '2002-07-18 09:58:00.000000', NULL, 1),
(85299, 3213, 2481, '<td valign="top">could be a dynamite photo with more focus, lights and shadows; it gets lost</td>', 'could be a dynamite photo with more focus, lights and shadows; it gets lost', '2002-07-18 10:08:00.000000', NULL, 1),
(85300, 3213, 2373, '<td valign="top">I wish it were in focus more, otherwise nice.</td>', 'I wish it were in focus more, otherwise nice.', '2002-07-18 15:25:00.000000', NULL, 1),
(85301, 3213, 587, '<td valign="top">Sorry, fish to me, are supposed to be bright and vibrantly colored with green grasses to hide in as well as pretty rocks - I guess I''m tryin to say I''m not a big fan of the color theme you chose here, and the air bubbles are distracting and it''s so dark you can hardly see anything clearly. Brighten up! ;)  3 cthenk</td>', 'Sorry, fish to me, are supposed to be bright and vibrantly colored with green grasses to hide in as well as pretty rocks - I guess I''m tryin to say I''m not a big fan of the color theme you chose here, and the air bubbles are distracting and it''s so dark you can hardly see anything clearly. Brighten up! ;)  3 cthenk', '2002-07-18 17:50:00.000000', NULL, 1),
(85302, 3213, 2783, '<td valign="top">Did astronauts take this into space?<br/><br/>Just kidding-8</td>', 'Did astronauts take this into space?Just kidding-8', '2002-07-19 02:55:00.000000', NULL, 1),
(85303, 3213, 640, '<td valign="top">focus</td>', 'focus', '2002-07-19 04:21:00.000000', NULL, 1),
