(85305, 3213, 2801, '<td valign="top">Bad focus.</td>', 'Bad focus.', '2002-07-20 01:20:00.000000', NULL, 1),
(85306, 3213, 637, '<td valign="top">Little too much going on here for my taste...Pinkish tint is a turnoff too... 4 sjgleah</td>', 'Little too much going on here for my taste...Pinkish tint is a turnoff too... 4 sjgleah', '2002-07-20 03:04:00.000000', NULL, 1),
