(85664, 3232, 2481, '<td valign="top">nice perspective shot study</td>', 'nice perspective shot study', '2002-07-18 09:44:00.000000', NULL, 1),
(85665, 3232, 1041, '<td valign="top">i''m trying to figure out what station you took this one in ... looks like it''s on the northern line if i remember correctly (it''s been a while ...).  anyway, perspective is nice, but it''s not the most interesting shot to me (beyond trying to figure out the exact location ;), and could do with a tad more sharpening. -- gr8photos (5)</td>', 'i''m trying to figure out what station you took this one in ... looks like it''s on the northern line if i remember correctly (it''s been a while ...).  anyway, perspective is nice, but it''s not the most interesting shot to me (beyond trying to figure out the exact location ;), and could do with a tad more sharpening. -- gr8photos (5)', '2002-07-18 17:58:00.000000', NULL, 1),
(85666, 3232, 878, '<td valign="top">Clean shot and subway.</td>', 'Clean shot and subway.', '2002-07-19 00:24:00.000000', NULL, 1),
(85667, 3232, 2777, '<td valign="top">OK, but not very interesting, some people moving in the foreground will add some dynamics.</td>', 'OK, but not very interesting, some people moving in the foreground will add some dynamics.', '2002-07-19 06:35:00.000000', NULL, 1),
(85668, 3232, 1175, '<td valign="top">I like the depth.</td>', 'I like the depth.', '2002-07-19 15:22:00.000000', NULL, 1),
