(86703, 3284, 714, '<td valign="top">Very colorful and different from the other photos.  Seems grainy but will still give you a 6.</td>', 'Very colorful and different from the other photos.  Seems grainy but will still give you a 6.', '2002-07-15 17:42:00.000000', NULL, 1),
(86704, 3284, 2350, '<td valign="top">colorful</td>', 'colorful', '2002-07-15 18:48:00.000000', NULL, 1),
