(87516, 3320, 2261, '<td valign="top">If you like indian gear this is great.</td>', 'If you like indian gear this is great.', '2002-07-16 17:50:00.000000', NULL, 1),
(87517, 3320, 409, '<td valign="top">!</td>', '!', '2002-07-16 19:05:00.000000', NULL, 1),
