(87649, 3323, 1003, '<td valign="top">such great detail</td>', 'such great detail', '2002-07-19 05:17:00.000000', NULL, 1),
(87650, 3323, 917, '<td valign="top">An extremely difficult shot. Its can be improved upon, fewer reflections, sharper image, better contract with background, etc. But Im still giving it a 10. Did you refridgerate it or use a dead bee at all?</td>', 'An extremely difficult shot. Its can be improved upon, fewer reflections, sharper image, better contract with background, etc. But Im still giving it a 10. Did you refridgerate it or use a dead bee at all?', '2002-07-19 08:16:00.000000', NULL, 1),
(87651, 3323, 1202, '<td valign="top">Composition10,<br/>Technical Aspects10,<br/>Meets Challenge10,<br/>Originality10,<br/>Average Score10,<br/>Autool.<br/><br/></td>', 'Composition10,Technical Aspects10,Meets Challenge10,Originality10,Average Score10,Autool.', '2002-07-19 10:25:00.000000', NULL, 1),
