(87690, 3327, 2815, '<td valign="top">I love the colors</td>', 'I love the colors', '2002-07-20 17:06:00.000000', NULL, 1),
(87691, 3327, 811, '<td valign="top">Gorgeous colors, fantastic focus, clear lighting.  This is very nice.  Great job.</td>', 'Gorgeous colors, fantastic focus, clear lighting.  This is very nice.  Great job.', '2002-07-20 23:19:00.000000', NULL, 1),
(87692, 3327, 2752, '<td valign="top">great</td>', 'great', '2002-07-21 01:28:00.000000', NULL, 1),
