(88848, 3383, 2380, '<td valign="top">THE STAIRWAY TO HEAVEN AINT VERY CLEAN !!</td>', 'THE STAIRWAY TO HEAVEN AINT VERY CLEAN !!', '2002-07-17 12:38:00.000000', NULL, 1),
(88849, 3383, 671, '<td valign="top">nice architecture study.  The absolutely blue sky backdrop works well.</td>', 'nice architecture study.  The absolutely blue sky backdrop works well.', '2002-07-17 13:24:00.000000', NULL, 1),
(88850, 3383, 2172, '<td valign="top">Really great photography....too bad the building itself isn''t any cleaner, would''ve been even more dramatic with solid grey vs blue--doesn''t matter.  Great angle and colors.  Wonderful job!<br/>Ruthann</td>', 'Really great photography....too bad the building itself isn''t any cleaner, would''ve been even more dramatic with solid grey vs blue--doesn''t matter.  Great angle and colors.  Wonderful job!Ruthann', '2002-07-17 18:15:00.000000', NULL, 1),
(88851, 3383, 1031, '<td valign="top">I think I''d have tried cropping narrower and/or over to the left a bit to as to make it seem as though the "stairs" continue up and out of the frame to the upper right.</td>', 'I think I''d have tried cropping narrower and/or over to the left a bit to as to make it seem as though the "stairs" continue up and out of the frame to the upper right.', '2002-07-18 03:38:00.000000', NULL, 1),
(88852, 3383, 1707, '<td valign="top">a modern pyramid?</td>', 'a modern pyramid?', '2002-07-18 05:28:00.000000', NULL, 1),
(88853, 3383, 2777, '<td valign="top">A little bit boring, uniteresting colors, maybe b&amp;w would work better.</td>', 'A little bit boring, uniteresting colors, maybe b&w would work better.', '2002-07-18 09:25:00.000000', NULL, 1),
(88854, 3383, 2481, '<td valign="top">very graphic, good focus</td>', 'very graphic, good focus', '2002-07-18 09:52:00.000000', NULL, 1),
