(88857, 3383, 692, '<td valign="top">interesting</td>', 'interesting', '2002-07-19 22:53:00.000000', NULL, 1),
(88858, 3383, 2801, '<td valign="top">interesting architecture shot. nice crop.</td>', 'interesting architecture shot. nice crop.', '2002-07-20 01:27:00.000000', NULL, 1),
(88859, 3383, 2752, '<td valign="top">clever use of building</td>', 'clever use of building', '2002-07-20 23:21:00.000000', NULL, 1),
(88860, 3383, 472, '<td valign="top">good abstract ..</td>', 'good abstract ..', '2002-07-21 16:55:00.000000', NULL, 1),
(88861, 3383, 1078, '<td valign="top">Don''t know about the title ;-)  but I like the simple shot.  Nicely geometric against a pretty blue sky.   I think the color of the sky nicely accentuates the grey of the building.</td>', 'Don''t know about the title ;-)  but I like the simple shot.  Nicely geometric against a pretty blue sky.   I think the color of the sky nicely accentuates the grey of the building.', '2002-07-21 17:09:00.000000', NULL, 1),
(88862, 3383, 2825, '<td valign="top">good rythm, colours and composition</td>', 'good rythm, colours and composition', '2002-07-21 20:01:00.000000', NULL, 1),
(88863, 3383, 2188, '<td valign="top">I like this. Nice repetition and angle.</td>', 'I like this. Nice repetition and angle.', '2002-07-22 00:43:00.000000', NULL, 1),
(88864, 3385, 2123, '<td valign="top">Great color! 7</td>', 'Great color! 7', '2002-07-15 01:45:00.000000', NULL, 1),
(88865, 3385, 1877, '<td valign="top">Hmm.. I like the brightness.. I would have cropped it so that the photo top starts at the tops of the candles and the photo''s bottom is at the bottom of the second row of candles. Something like that. 6</td>', 'Hmm.. I like the brightness.. I would have cropped it so that the photo top starts at the tops of the candles and the photo''s bottom is at the bottom of the second row of candles. Something like that. 6', '2002-07-15 02:24:00.000000', NULL, 1),
(88866, 3385, 889, '<td valign="top">Interesting colors though slighty over saturated,</td>', 'Interesting colors though slighty over saturated,', '2002-07-15 04:13:00.000000', NULL, 1),
(88867, 3385, 2261, '<td valign="top">Fantastic colours, shame all the boxes wern''t full.</td>', 'Fantastic colours, shame all the boxes wern''t full.', '2002-07-15 14:09:00.000000', NULL, 1),
(88868, 3385, 327, '<td valign="top">Lovely colors and a good eye. I think a tripod would of helped this shot to an 8. Kee</td>', 'Lovely colors and a good eye. I think a tripod would of helped this shot to an 8. Kee', '2002-07-15 14:11:00.000000', NULL, 1),
(88869, 3385, 737, '<td valign="top">Looks a little oversaturated in places.</td>', 'Looks a little oversaturated in places.', '2002-07-15 15:14:00.000000', NULL, 1),
(88870, 3385, 2058, '<td valign="top">I think the same subject with a different angle, not straight on, would have looked better.  Very colorful!</td>', 'I think the same subject with a different angle, not straight on, would have looked better.  Very colorful!', '2002-07-15 17:21:00.000000', NULL, 1),
(88871, 3385, 573, '<td valign="top">Very colorfull.</td>', 'Very colorfull.', '2002-07-15 18:04:00.000000', NULL, 1),
(88872, 3385, 1005, '<td valign="top">Nice florescent colored candles.  Well taken shot, but did you arrange the candles?  If you did, ignore the following:  No creative addition from photographer.  Two points for the candle maker, 2 points for the store''s stock person, and 4 points to the photographer.  (yes, they get half your points, please see they get credit)<br/>4 Swash</td>', 'Nice florescent colored candles.  Well taken shot, but did you arrange the candles?  If you did, ignore the following:  No creative addition from photographer.  Two points for the candle maker, 2 points for the store''s stock person, and 4 points to the photographer.  (yes, they get half your points, please see they get credit)4 Swash', '2002-07-15 19:05:00.000000', NULL, 1),
(88873, 3385, 1543, '<td valign="top">vibrant colors</td>', 'vibrant colors', '2002-07-15 21:28:00.000000', NULL, 1),
(88874, 3385, 2661, '<td valign="top">Very colorful indeed. I would pay 80 cents for one. Nice photo.</td>', 'Very colorful indeed. I would pay 80 cents for one. Nice photo.', '2002-07-16 03:19:00.000000', NULL, 1),
(88875, 3385, 656, '<td valign="top">colourful - but doesn''t do a whole lot to grab me.</td>', 'colourful - but doesn''t do a whole lot to grab me.', '2002-07-16 10:23:00.000000', NULL, 1),
(88876, 3385, 772, '<td valign="top">this is a neat study in color... The uneven edge along the bottom right portion of the photo is a little distracting... = 6 - jmsetzler</td>', 'this is a neat study in color... The uneven edge along the bottom right portion of the photo is a little distracting... = 6 - jmsetzler', '2002-07-16 16:07:00.000000', NULL, 1),
(88877, 3385, 2295, '<td valign="top">Nice picture.  Very colorful, well laid out.  Good lighting and focus.</td>', 'Nice picture.  Very colorful, well laid out.  Good lighting and focus.', '2002-07-16 17:07:00.000000', NULL, 1),
(88878, 3385, 2370, '<td valign="top">nice play of colors!</td>', 'nice play of colors!', '2002-07-17 04:18:00.000000', NULL, 1),
(88879, 3385, 2650, '<td valign="top">great colors.</td>', 'great colors.', '2002-07-17 11:20:00.000000', NULL, 1),
(88880, 3385, 2334, '<td valign="top">Great colours.</td>', 'Great colours.', '2002-07-17 11:43:00.000000', NULL, 1),
(88881, 3385, 2764, '<td valign="top">This is my favorite picture!  I think it''s the colors.</td>', 'This is my favorite picture!  I think it''s the colors.', '2002-07-17 14:59:00.000000', NULL, 1),
(88882, 3385, 641, '<td valign="top">I''ve never seen candles so colorful :)</td>', 'I''ve never seen candles so colorful :)', '2002-07-17 15:09:00.000000', NULL, 1),
(88883, 3385, 2111, '<td valign="top">colorful 5</td>', 'colorful 5', '2002-07-17 17:30:00.000000', NULL, 1),
(88884, 3385, 1897, '<td valign="top">interesting, I think I would have liked it more without the table edge.</td>', 'interesting, I think I would have liked it more without the table edge.', '2002-07-18 00:04:00.000000', NULL, 1),
(88885, 3385, 878, '<td valign="top">Nice color subject.</td>', 'Nice color subject.', '2002-07-18 00:16:00.000000', NULL, 1),
(88886, 3385, 1707, '<td valign="top">the horizontal is off, particulary showing in the lower right corner compared to lower left corner.</td>', 'the horizontal is off, particulary showing in the lower right corner compared to lower left corner.', '2002-07-18 03:31:00.000000', NULL, 1),
(88887, 3385, 2481, '<td valign="top">closer shot might have been more effective; bottom of photo doesn''t do anything for it; nice colors, linear directions are good</td>', 'closer shot might have been more effective; bottom of photo doesn''t do anything for it; nice colors, linear directions are good', '2002-07-18 09:42:00.000000', NULL, 1),
(88888, 3385, 2373, '<td valign="top">Either the color or the contrast or the quality seems to be of just a bit. Otherwise very colorful pic</td>', 'Either the color or the contrast or the quality seems to be of just a bit. Otherwise very colorful pic', '2002-07-18 15:23:00.000000', NULL, 1),
