INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(90090, 3430, 1793, '<td valign="top">hmm. i think if more green was in the photograph it would make this more visually interesting and balanced.</td>', 'hmm. i think if more green was in the photograph it would make this more visually interesting and balanced.', '2002-07-17 04:14:00.000000', NULL, 1),
(90091, 3430, 1175, '<td valign="top">This would be a beautiful image if it just had more focus.</td>', 'This would be a beautiful image if it just had more focus.', '2002-07-17 10:05:00.000000', NULL, 1),
(90092, 3430, 1042, '<td valign="top">I really like this shot. The only thing that bothers me are the out of focus parts of it. But I think the set-up and cropping of it is great. I''d just like to see it a little sharper. 7 - KDJohnson</td>', 'I really like this shot. The only thing that bothers me are the out of focus parts of it. But I think the set-up and cropping of it is great. I''d just like to see it a little sharper. 7 - KDJohnson', '2002-07-17 11:31:00.000000', NULL, 1),
(90093, 3430, 671, '<td valign="top">7  great colors, good framing.</td>', '7  great colors, good framing.', '2002-07-17 12:13:00.000000', NULL, 1),
(90094, 3430, 2334, '<td valign="top">nice concept, but it would''ve been a lot better if it was in focus.</td>', 'nice concept, but it would''ve been a lot better if it was in focus.', '2002-07-17 14:01:00.000000', NULL, 1),
(90095, 3430, 441, '<td valign="top">looks like focus missed or shake - would have been beautiful otherwise</td>', 'looks like focus missed or shake - would have been beautiful otherwise', '2002-07-17 18:31:00.000000', NULL, 1),
(90096, 3430, 1003, '<td valign="top">needs focus, good subject</td>', 'needs focus, good subject', '2002-07-17 22:51:00.000000', NULL, 1),
(90097, 3430, 2370, '<td valign="top">could do with a little sharpening.. not in focus too.</td>', 'could do with a little sharpening.. not in focus too.', '2002-07-18 01:18:00.000000', NULL, 1),
(90098, 3430, 2481, '<td valign="top">macro closeups need distinct focus - even a tad can throw it off; nice colors though</td>', 'macro closeups need distinct focus - even a tad can throw it off; nice colors though', '2002-07-18 09:57:00.000000', NULL, 1),
(90099, 3430, 885, '<td valign="top">Nice composition and color...but this could have really really benefited from some more depth of field.</td>', 'Nice composition and color...but this could have really really benefited from some more depth of field.', '2002-07-18 14:18:00.000000', NULL, 1),
(90100, 3430, 1041, '<td valign="top">macros are hard because the DOF becomes very shallow.  if there was a way for you to increase it here it would make for a better photo.  i do like the crop to just photograph part of the flower.  would be good for the texture challenge, too, don''t you think? -- gr8photos (4)</td>', 'macros are hard because the DOF becomes very shallow.  if there was a way for you to increase it here it would make for a better photo.  i do like the crop to just photograph part of the flower.  would be good for the texture challenge, too, don''t you think? -- gr8photos (4)', '2002-07-18 16:56:00.000000', NULL, 1),
(90101, 3430, 878, '<td valign="top">My kind of shot.</td>', 'My kind of shot.', '2002-07-18 23:37:00.000000', NULL, 1),
(90102, 3430, 640, '<td valign="top">focus</td>', 'focus', '2002-07-19 01:42:00.000000', NULL, 1),
